ALTER TABLE "git_connections" DROP CONSTRAINT "git_connections_credential_key_id";--> statement-breakpoint
ALTER TABLE "git_connections" DROP CONSTRAINT "git_connections_capabilities";--> statement-breakpoint
DROP INDEX "git_repositories_host_unique";--> statement-breakpoint
ALTER TABLE "git_connections" ALTER COLUMN "capabilities" SET DEFAULT '{"create":"unknown","read":"unknown","write":"unknown","admin":"unknown"}'::jsonb;--> statement-breakpoint
ALTER TABLE "git_connections" ADD COLUMN "excess_permissions" text[] DEFAULT '{}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "git_repositories" ADD COLUMN "base_url" text NOT NULL;--> statement-breakpoint
CREATE INDEX "git_repositories_connection_idx" ON "git_repositories" USING btree ("team_id","connection_id");--> statement-breakpoint
CREATE UNIQUE INDEX "git_repositories_host_unique" ON "git_repositories" USING btree ("team_id","base_url","host_repo_id");--> statement-breakpoint
ALTER TABLE "git_connections" ADD CONSTRAINT "git_connections_excess_permissions" CHECK (array_ndims("git_connections"."excess_permissions") IS DISTINCT FROM 2 AND cardinality("git_connections"."excess_permissions") <= 50 AND array_position("git_connections"."excess_permissions", NULL) IS NULL AND char_length(array_to_string("git_connections"."excess_permissions", '')) <= 5000);--> statement-breakpoint
ALTER TABLE "git_connections" ADD CONSTRAINT "git_connections_credential_key_id" CHECK (char_length("git_connections"."credential_key_id") BETWEEN 1 AND 64 AND "git_connections"."credential_key_id" = split_part("git_connections"."credential_sealed", '.', 2));--> statement-breakpoint
ALTER TABLE "git_connections" ADD CONSTRAINT "git_connections_capabilities" CHECK (jsonb_typeof("git_connections"."capabilities") = 'object' AND "git_connections"."capabilities" - ARRAY['create', 'read', 'write', 'admin'] = '{}'::jsonb AND coalesce("capabilities" ->> 'create', '') IN ('yes', 'no', 'unknown') AND coalesce("capabilities" ->> 'read', '') IN ('yes', 'no', 'unknown') AND coalesce("capabilities" ->> 'write', '') IN ('yes', 'no', 'unknown') AND coalesce("capabilities" ->> 'admin', '') IN ('yes', 'no', 'unknown'));--> statement-breakpoint
ALTER TABLE "git_repositories" ADD CONSTRAINT "git_repositories_base_url" CHECK (char_length("git_repositories"."base_url") <= 2048 AND "git_repositories"."base_url" ~ '^https://[a-z0-9.-]+(:[0-9]{1,5})?(/[^?#[:space:]]*[^/?#[:space:]])?$');